style.css:
body::before {
  content: "";
  position: fixed;
  top: 50%;
  left: 50%;
  width: 50px;
  height: 50px;
  margin-left: -25px;
  margin-top: -25px;
  background-color: white;
  z-index: 9999;
  pointer-events: none;
  animation: spinFade 1.3s linear forwards;
  transform-style: preserve-3d;
  border-radius: 5px;
  box-shadow: 0 0 0 100vw rgba(0,0,0,1);
}

@keyframes spinFade {
  0% {
    transform: rotateZ(0deg);
    background-color: white;
    box-shadow: 0 0 0 100vw rgba(0,0,0,1);
  }
  100% {
    transform: rotateZ(720deg);
    background-color: rgba(255,255,255,0);
    box-shadow: 0 0 0 100vw rgba(0,0,0,0);
  }
}
